const STATUS_RE = /^\/status\s+(.+?)\s*$/;
const UPDATE_RE = /^\/update\s+(.+?)\s+(\S+)\s*$/;

function parseMessage(text) {
  text = text.trim();

  let m = text.match(STATUS_RE);
  if (m) {
    return {
      command: "status",
      contact_name: m[1].trim(),
      new_status: null,
    };
  }

  m = text.match(UPDATE_RE);
  if (m) {
    return {
      command: "update",
      contact_name: m[1].trim(),
      new_status: m[2].trim(),
    };
  }

  throw new Error("Invalid command format");
}

const inputMessage = $('Telegram Trigger').first().json.message.text;
const parsed = parseMessage(inputMessage);

return [{ json: parsed }];

function parseInput(text) {
  const input = text.trim();
  const [kind, ...rest] = input.split(/\s+/);
  const command = kind.split("<")[0];
  const id_value = rest.join(" ").trim();

  switch (command) {
    case "GET_STATUS":
      if (!id_value) throw new Error("Missing ID value");
      return { type: kind, id: id_value };

    case "SET_STATUS":
      if (!id_value) throw new Error("Missing ID value");
      return { type: kind, id: id_value };

    case "SET_TASK_DONE":
      if (!id_value) throw new Error("Missing ID value");
      return { type: kind, id: id_value };

    default:
      throw new Error("Invalid input. Expected 'SET_TASK_DONE <value>', 'GET_STATUS <value>', or 'SET_STATUS <value>'");
  }
}

const inputText = $('Telegram Trigger').first().json.callback_query.data;

const parsed = parseInput(inputText);

return [{ json: parsed }];

const items = $input.all();

const action = ({
  status: "GET_STATUS",
  update: "SET_STATUS<" + $('Parse Slash Command').first().json.new_status + ">",
})[$('Parse Slash Command').first().json.command];

if (!action) throw new Error("Invalid command");

const buttons = items.map((item) => ([
  {
    text: item.json.name,
    callback_data: action + ' ' + String(item.json.id),
  }
]));

return [{
  json: {
    chat_id: $('Telegram Trigger').first().json.message.chat.id,
    text: "Choose one:",
    reply_markup: {
      inline_keyboard: buttons
    }
  }
}];

const input = $input.first().json;

const command = input.type.split("<")[0];
const new_status = input.type.split("<")[1].replace(/>$/, "");
const id = input.id;

return [
  {
    json: {
      command: command,
      id: id,
      new_status: new_status,
    },
  },
];

